```java
import java.util.*;

public class Main {
    record Head(int value, Iterator<Integer> rest) {}

    static void mergeRuns(List<List<Integer>> runs) {
        PriorityQueue<Head> heap = new PriorityQueue<>(Comparator.comparingInt(Head::value));
        for (List<Integer> run : runs) {
            Iterator<Integer> it = run.iterator();
            if (it.hasNext()) heap.add(new Head(it.next(), it));
        }
        while (!heap.isEmpty()) {
            Head h = heap.remove();
            System.out.println(h.value());
            Iterator<Integer> it = h.rest();
            if (it.hasNext()) heap.add(new Head(it.next(), it));
        }
    }

    public static void main(String[] args) {
        mergeRuns(List.of(List.of(1, 4), List.of(), List.of(2, 5)));
    }
}
```

